import numpy as np
import pandas as pd

DT_S = 2.0                               # logging period of the campaign: one row every 2 s
ALT_MIN_M, ALT_MAX_M = -100.0, 5000.0    # plausible altitudes for the course's vehicles
STATES = ("FIX", "DEGRADED", "NO_FIX")   # the judge's states, in this order
EARTH_RADIUS_M = 6_371_000.0             # the sphere of mission 06
MAD_TO_SIGMA = 1.4826                    # MAD × 1.4826 estimates σ when the errors are Gaussian


# given — read it and use it, no need to change it
def load_log(path):
    """Read a campaign CSV file into a DataFrame (empty cells become NaN).

    Example: load_log("some_log.csv") → a DataFrame with the 10 columns above, one row per line of the file
    """
    return pd.read_csv(path)


# given — read it and use it, no need to change it
def haversine_m(lat1, lon1, lat2, lon2):
    """Great-circle distance in metres between points given in degrees, on the sphere of radius
    EARTH_RADIUS_M. Works element by element on numbers, numpy arrays and pandas Series; NaN in → NaN out.
    (Mission 06 derives this formula and you write it there; here it is given.)

    Example: haversine_m(51.5074, -0.1278, 48.8566, 2.3522) → about 343 556   (London → Paris)
    """
    p1, p2 = np.radians(lat1), np.radians(lat2)
    a = np.sin((p2 - p1) / 2.0) ** 2 + np.cos(p1) * np.cos(p2) * np.sin(np.radians(lon2 - lon1) / 2.0) ** 2
    return 2.0 * EARTH_RADIUS_M * np.arcsin(np.sqrt(np.minimum(1.0, a)))


# given — read it and use it, no need to change it
def apply_corrections(df, clock_fix_s=None, speed_factor=None):
    """A corrected copy of a log: clock_fix_s = {flight_id: seconds added to that flight's time_s},
    speed_factor = {flight_id: factor multiplying that flight's speed_mps}. Other flights are unchanged.
    The raw file is never edited: corrections are data, kept apart and applied in code.

    Example: apply_corrections(df, {"f1": -60.0}, {"f2": 0.5}) → f1's times 60 s earlier, f2's speeds halved
    """
    out = df.copy()
    for fid, sec in (clock_fix_s or {}).items():
        m = out["flight_id"] == fid
        out.loc[m, "time_s"] = out.loc[m, "time_s"] + sec
    for fid, k in (speed_factor or {}).items():
        m = out["flight_id"] == fid
        out.loc[m, "speed_mps"] = out.loc[m, "speed_mps"] * k
    return out


